package com.example.statusdrafter.repository; import com.example.statusdrafter.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.*; import java.util.*;
public interface TaskRepository extends JpaRepository<Task,Long>{List<Task> findByEmployeeOrderByDeadlineAsc(User e); List<Task> findTop5ByEmployeeOrderByCreatedAtDesc(User e); long countByEmployee(User e); long countByEmployeeAndStatus(User e,Task.Status s); long countByStatus(Task.Status s); long countByStatusNot(Task.Status s); List<Task> findByDeadlineBetweenAndEmployeeOrderByDeadlineAsc(LocalDate a,LocalDate b,User e); List<Task> findByDeadlineBeforeAndStatusNotAndEmployeeOrderByDeadlineAsc(LocalDate d,Task.Status s,User e); List<Task> findByDeadlineBeforeAndStatusNotOrderByDeadlineAsc(LocalDate d,Task.Status s); List<Task> findByDeadlineBetweenAndStatusNotOrderByDeadlineAsc(LocalDate a,LocalDate b,Task.Status s); long countByEmployeeAndUpdatedAtBetween(User e,LocalDateTime a,LocalDateTime b);
 @Query("select t from Task t join fetch t.employee e where (:name is null or lower(t.taskName) like lower(concat('%',:name,'%'))) and (:emp is null or lower(e.name) like lower(concat('%',:emp,'%'))) and (:project is null or lower(t.project) like lower(concat('%',:project,'%'))) and (:status is null or t.status=:status) and (:priority is null or t.priority=:priority) and (:fromDate is null or t.startDate>=:fromDate) and (:toDate is null or t.deadline<=:toDate) order by t.deadline asc") List<Task> search(@Param("name")String name,@Param("emp")String emp,@Param("project")String project,@Param("status")Task.Status status,@Param("priority")Task.Priority priority,@Param("fromDate")LocalDate fromDate,@Param("toDate")LocalDate toDate);
}
